export const getListBoardActivityUrl = (boardId: number,
    params?: ListBoardActivityParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/boards/${boardId}/activity?${stringifiedParams}` : `/api/boards/${boardId}/activity`
}

